/** WS-ARCHSINCB03-DET: 240 posiciones. Importe 9(14)V99 en cero para la marca. */
public record RegistroB03Detalle(long numSec, String sucursal, String caja, long numTran,
                                 String claveTrans, int tipoMov, String medioAcceso,
                                 String sucPromotora, String contrato,   // 9(12) como String
                                 BigDecimal importe, int moneda, long referencia,
                                 int indMarcaOrdenante, LocalDate fecMarcaOrdenante) {}

@Component
@RequiredArgsConstructor
public class RegistroB03Mapper {
    private final P080Properties.B03 cfg;

    String detalle(Contrato c, long secuencia) {     // WS-NUM-AUT-ARCHSINCB03 PIC 9(08)
        var r = new RegistroB03Detalle(secuencia, cfg.sucursal(), cfg.caja(), secuencia,
                cfg.claveTransaccion(), cfg.tipoMovimiento(), cfg.medioAcceso(),
                cfg.sucursalPromotora(c.csi()), c.numContrato(),
                BigDecimal.ZERO.setScale(2), 0, 0L,
                c.numDato(1), c.fechaProcAct(1));
        return Fixed.b03Detalle(r);                   // 240 bytes, tipo de registro 2
    }
}
